pragma solidity ^0.8.20;

contract Crowdfunding {
    uint public fundingGoal;
    uint public deadline;
    address payable[] public contributors;

    mapping(address => uint) public contributions;

    event Contribute(address contributor, uint amount);
    event Withdrawal(address contributor, uint amount);

    constructor(uint _fundingGoal, uint _deadline) {
        fundingGoal = _fundingGoal * 10 ** 18; // convert to wei
        deadline = block.timestamp + _deadline;
    }

    function contribute() public payable {
        require(block.timestamp < deadline);

        contributions[msg.sender] += msg.value;
        contributors.push(msg.sender);

        emit Contribute(msg.sender, msg.value);
    }

    function withdraw() public {
        require(block.timestamp >= deadline);
        require(contributions[msg.sender] > 0);

        uint amount = contributions[msg.sender];
        contributors[contributors.length - 1] = msg.sender;
        delete contributions[msg.sender];

        payable(msg.sender).transfer(amount);
        emit Withdrawal(msg.sender, amount);
    }
}
