contract MultiOwnerWallet {
    mapping(address => uint) public ownerBalances;
    address[] public owners;

    event Transfer(address from, address to, uint amount);

    constructor() {
        owners.push(msg.sender);
    }

    function addOwner(address newOwner) external {
        require(owners.length < 3, "Wallet is full");
        require(newOwner != msg.sender, "Cannot be owner");

        owners.push(newOwner);
    }

    function transfer(address to, uint amount) external {
        require(ownerBalances[msg.sender] >= amount, "Not enough balance");
        require(msg.sender == owners[0] || msg.sender == owners[1], "Only owners can send ETH");

        ownerBalances[msg.sender] -= amount;
        ownerBalances[to] += amount;

        emit Transfer(msg.sender, to, amount);
    }

    function confirmTransfer(address from, address to, uint amount) external {
        require(ownerBalances[from] >= amount, "Not enough balance");
        require(msg.sender == owners[2], "Only second owner can send ETH");

        ownerBalances[from] -= amount;
        ownerBalances[to] += amount;
    }
}
