contract Vesting {
    address public beneficiary;
    uint256 public cliff;
    uint256 public start;
    uint256 public duration;

    constructor(address _beneficiary, uint256 _cliff, uint256 _duration) {
        beneficiary = _beneficiary;
        cliff = block.timestamp + _cliff;
        duration = _duration;
        start = block.timestamp;
    }

    function claim() external {
        require(msg.sender == beneficiary);
        require(block.timestamp >= cliff);

        uint256 amount = (block.timestamp - cliff) * getAmountPerSecond();
        transfer(beneficiary, amount);
    }

    function getAmountPerSecond() public view returns(uint256) {
        return (uint256(duration) * 10**18) / (cliff + duration);
    }

    function transfer(address to, uint256 value) private {
        (bool success, ) = to.call{value: value}("");
        require(success, "Transfer failed");
    }
}
